import {ElinaToonLook} from './toon-look.js';

// Exact renderer used by the existing character review. Runtime effects are
// supplied separately because FBX/glTF cannot encode screen-space ink passes.
export const NPC_LOOK=Object.freeze({mode:'toon',pbr:false,outline:true,outlinePixels:0.60,interior:true,interiorStrength:0.25,brightness:1.20});
export function createNpcLook(renderer,profile=NPC_LOOK){
  const look=new ElinaToonLook(renderer);
  look.width=profile.outlinePixels;look.outlined=profile.outline;
  look.interior.enabled=profile.interior;look.interior.strength=profile.interiorStrength;
  look.interior.scale=1.85;
  renderer.toneMappingExposure=profile.brightness;
  return look;
}

