import * as T from 'three';
import {OutlineEffect} from './silhouette-effect.js';
import {InteriorInk} from './interior-ink.js';

// Same ink profile as Joachim's hero-matched look; no internal hull contours.
export const HERO_INK={color:[.028,.022,.030],pixels:.55,mode:'stencil exterior silhouette only'};
export class ElinaToonLook{
  constructor(renderer){
    this.renderer=renderer;this.width=HERO_INK.pixels;this.outlined=true;
    this.sunWorld=new T.Vector3(-.35,.65,.75).normalize();this.sunView={value:new T.Vector3()};
    this.effect=new OutlineEffect(renderer,{defaultThickness:.001,defaultColor:HERO_INK.color,defaultKeepAlive:true});
    this.effect.autoClear=true;this.cache=new Map();this.activeMaterials=new Set();
    this.interior=new InteriorInk(renderer);
  }
  material(original,mode){
    if(mode==='material')return original;
    const key=original.uuid+':'+mode;
    if(this.cache.has(key))return this.cache.get(key);
    const baseMap=original.map||original.emissiveMap;
    const baseColor=!original.map&&original.emissiveMap?original.emissive:original.color;
    const common={name:'Elina_'+mode,map:mode==='clay'?null:baseMap,color:mode==='clay'?0xaaa39c:baseColor,side:T.DoubleSide,transparent:original.transparent,opacity:original.opacity,alphaTest:original.alphaTest};
    let mat;
    if(mode==='toon'){
      mat=new T.MeshToonMaterial(common);
      // Retain the painted base colour and add the village's bright diffuse bands.
      // Metal, roughness, normal, reflection and specular maps are intentionally absent.
      mat.onBeforeCompile=shader=>{
        shader.uniforms.elinaSunView=this.sunView;
        shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nuniform vec3 elinaSunView;');
        shader.fragmentShader=shader.fragmentShader.replace('vec3 outgoingLight = reflectedLight.directDiffuse + reflectedLight.indirectDiffuse + totalEmissiveRadiance;',`
          float elinaFacing=dot(normalize(normal),normalize(elinaSunView));
          float elinaBand=.78+.14*smoothstep(-.10,-.02,elinaFacing)+.12*smoothstep(.48,.56,elinaFacing);
          vec3 outgoingLight=diffuseColor.rgb*elinaBand;
        `);
      };
      mat.customProgramCacheKey=()=> 'elina-hero-bright-toon-v1';
    }else if(mode==='clay')mat=new T.MeshStandardMaterial({...common,roughness:.85});
    else mat=new T.MeshBasicMaterial(common);
    this.cache.set(key,mat);return mat;
  }
  apply(model,mode){
    this.activeMaterials.clear();
    model.traverse(mesh=>{
      if(!mesh.isMesh)return;
      mesh.userData.reviewOriginal??=mesh.material;
      const source=mesh.userData.reviewOriginal;
      const convert=original=>{
        const mat=this.material(original,mode);
        Object.assign(mat,{stencilWrite:true,stencilRef:1,stencilWriteMask:1,stencilFunc:T.AlwaysStencilFunc,stencilZPass:T.ReplaceStencilOp});
        mat.userData.outlineParameters={visible:true,thickness:.001,color:HERO_INK.color,keepAlive:true};
        this.activeMaterials.add(mat);return mat;
      };
      mesh.material=Array.isArray(source)?source.map(convert):convert(source);
    });
    this.mode=mode;
  }
  render(scene,camera,height){
    camera.updateMatrixWorld();
    this.sunView.value.copy(this.sunWorld).transformDirection(camera.matrixWorldInverse);
    for(const mat of this.activeMaterials)mat.userData.outlineParameters.thickness=this.width*2/height;
    if(this.interior.enabled)this.interior.capture(scene,camera);
    this.effect.enabled=this.outlined;this.effect.render(scene,camera);
    if(this.interior.enabled)this.interior.draw();
  }
}

