import * as T from 'three';

// Geometry contours: depth breaks and strong normal changes, never triangle edges.
export class InteriorInk{
  constructor(renderer){
    this.renderer=renderer;this.enabled=true;this.strength=.75;this.width=.8;this.scale=1;
    this.target=new T.WebGLRenderTarget(1,1,{minFilter:T.NearestFilter,magFilter:T.NearestFilter,depthBuffer:true});
    this.target.texture.colorSpace=T.NoColorSpace;this.target.depthTexture=new T.DepthTexture(1,1,T.UnsignedIntType);
    this.normalMaterial=new T.MeshNormalMaterial({side:T.DoubleSide});this.normalMaterial.toneMapped=false;
    this.u={tNormal:{value:this.target.texture},tDepth:{value:this.target.depthTexture},texel:{value:new T.Vector2()},nearFar:{value:new T.Vector2()},pixelWorldFactor:{value:0},scale:{value:1},strength:{value:.75},ink:{value:new T.Color().setRGB(.052,.040,.054)}};
    this.material=new T.ShaderMaterial({uniforms:this.u,transparent:true,depthTest:false,depthWrite:false,toneMapped:false,
      vertexShader:`varying vec2 vUv;void main(){vUv=uv;gl_Position=vec4(position.xy,0.,1.);}`,
      fragmentShader:`
        #include <common>
        #include <packing>
        varying vec2 vUv;uniform sampler2D tNormal,tDepth;uniform vec2 texel,nearFar;uniform float pixelWorldFactor,scale,strength;uniform vec3 ink;
        float distanceAt(vec2 uv){return -perspectiveDepthToViewZ(texture2D(tDepth,uv).r,nearFar.x,nearFar.y);}
        float edgeAt(vec2 off,vec3 n,float z){
          vec2 uv=vUv+off*texel;vec4 other=texture2D(tNormal,uv);if(other.a<.5)return 0.;
          vec3 nn=normalize(other.rgb*2.-1.);float dz=distanceAt(uv)-z;
          float slope=(abs(n.x*off.x)+abs(n.y*off.y))/max(.22,abs(n.z));
          float threshold=max(.0008*scale,z*pixelWorldFactor*1.4)+z*pixelWorldFactor*slope*1.8;
          float depthLine=smoothstep(threshold,threshold*2.4,dz);
          float normalLine=smoothstep(.16,.40,1.-dot(n,nn));
          return max(depthLine,normalLine*.78);
        }
        void main(){
          vec4 center=texture2D(tNormal,vUv);if(center.a<.5)discard;
          vec3 n=normalize(center.rgb*2.-1.);float z=distanceAt(vUv);float e=0.;
          e=max(e,edgeAt(vec2(1,0),n,z));e=max(e,edgeAt(vec2(-1,0),n,z));e=max(e,edgeAt(vec2(0,1),n,z));e=max(e,edgeAt(vec2(0,-1),n,z));
          e=max(e,edgeAt(vec2(.707,.707),n,z));e=max(e,edgeAt(vec2(-.707,.707),n,z));e=max(e,edgeAt(vec2(.707,-.707),n,z));e=max(e,edgeAt(vec2(-.707,-.707),n,z));
          if(e<.035)discard;gl_FragColor=vec4(ink,clamp(e*strength,0.,.9));
          #include <colorspace_fragment>
        }`});
    this.quadScene=new T.Scene();this.quadCamera=new T.OrthographicCamera(-1,1,1,-1,0,1);this.quadScene.add(new T.Mesh(new T.PlaneGeometry(2,2),this.material));this.size=new T.Vector2();
  }
  capture(scene,camera){
    const r=this.renderer;r.getDrawingBufferSize(this.size);
    if(this.target.width!==this.size.x||this.target.height!==this.size.y)this.target.setSize(this.size.x,this.size.y);
    const oldTarget=r.getRenderTarget(),background=scene.background,override=scene.overrideMaterial,clear=r.getClearColor(new T.Color()),alpha=r.getClearAlpha();
    const layerMask=camera.layers.mask;camera.layers.set(1);scene.background=null;scene.overrideMaterial=this.normalMaterial;r.setRenderTarget(this.target);r.setClearColor(0,0);r.clear();r.render(scene,camera);
    camera.layers.mask=layerMask;scene.background=background;scene.overrideMaterial=override;r.setRenderTarget(oldTarget);r.setClearColor(clear,alpha);
    this.u.texel.value.set(this.width*r.getPixelRatio()/this.size.x,this.width*r.getPixelRatio()/this.size.y);this.u.nearFar.value.set(camera.near,camera.far);
    this.u.pixelWorldFactor.value=2*Math.tan(T.MathUtils.degToRad(camera.fov*.5))/(this.size.y/r.getPixelRatio());this.u.scale.value=this.scale;this.u.strength.value=this.strength;
  }
  draw(){const r=this.renderer,clear=r.autoClear;r.autoClear=false;r.render(this.quadScene,this.quadCamera);r.autoClear=clear;}
}

